def aggregate_sign_and_abs(nums):
    if not nums:
        return None
    product_sign = 1
    sum_abs = 0
    for n in nums:
        # ensure sign is 1, -1 or 0, if not, will infer sign by comparing n
        if n > 0:
            sign = 1
        elif n < 0:
            sign = -1
        else:
            sign = 0
        product_sign *= sign
        sum_abs += abs(n)
    return product_sign + sum_abs

