        for length in range(1, len(s) + 1):
            num = int(s[:length])
            if num <= target:
                if can_partition(s[length:], target - num):
                    return True
        return False

    total = 0
    for i in range(1, n + 1):
        sq_str = str(i * i)
        if can_partition(sq_str, i):
            total += i * i
    return total
