def change_case_and_encode(message: str) -> str:
    # Swap case first
    swapped = message.swapcase()

    # Function to shift vowel by two spots alphabetically, wrapping within a-z or A-Z
    def shift_vowel(ch):
        if ch.islower():
            base = ord('a')
            offset = (ord(ch) - base + 2) % 26
            return chr(base + offset)
        elif ch.isupper():
            base = ord('A')
            offset = (ord(ch) - base + 2) % 26
            return chr(base + offset)
        else:
            return ch

    vowels_lower = 'aeiou'
    vowels_upper = 'AEIOU'

    result_chars = []
    for ch in swapped:
        if ch in vowels_lower or ch in vowels_upper:
            result_chars.append(shift_vowel(ch))
        else:
            result_chars.append(ch)

    result_str = ''.join(result_chars)

    # Encode uniquely by converting each char to its unicode code point in hex, separated by '-'
    encoded = '-'.join(f"{ord(c):04x}" for c in result_str)
    return encoded

