    """
    Given a string s, perform exactly one operation to get the smallest lexicographical string possible.
    Operation options (choose exactly one):
    1) Pick any substring and reverse it.
    2) Pick any substring and change each character to the one before it in the alphabet 
        (with 'a' -> 'z' wraparound).

    Return the lex smallest string obtainable by exactly one such operation.
    """
    n = len(s)
    res = s

    # Operation 1: reverse substring
    for i in range(n):
        for j in range(i + 1, n + 1):
            candidate = s[:i] + s[i:j][::-1] + s[j:]
            if candidate < res:
                res = candidate

    # Operation 2: decrement substring characters by one with wraparound
    for i in range(n):
        for j in range(i + 1, n + 1):
            decremented_substring = []
            for c in s[i:j]:
                if c == 'a':
