def max_jumps(arr, target):
    from collections import deque

    n = len(arr)
    if n == 1:
        return 0

    # Build graph of reachable indices
    graph = [[] for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            diff = arr[j] - arr[i]
            if -target <= diff <= target:
                graph[i].append(j)

    # Use BFS to find max jumps needed (longest path in DAG from 0 to n-1)
    # Because we want maximum number of jumps, we can use DP with topological order
    # The graph edges go only forward (j > i), so no cycles

    dp = [-1] * n  # dp[i] = max jumps to reach i
    dp[0] = 0

    for i in range(n):
        if dp[i] == -1:
            continue
        for j in graph[i]:
            if dp[j] < dp[i] + 1:
                dp[j] = dp[i] + 1

    return dp[-1] if dp[-1] != -1 else -1

