def ways_to_express_unique_powers(n):
    # Generate all unique powers of integers >=2 that are <= n
    powers = set()
    max_base = int(n**0.5) + 2  # upper estimate for base

    # Since powers >=2^0=1; but 1 repeated doesn't add uniqueness, we consider powers from base^1 onwards
    # To cover the numbers, try bases from 2 up to n, generate powers <= n
    # But to optimize, since powers grow fast, we only generate powers <= n
    for base in range(2, n+1):
        val = base
        while val <= n:
            powers.add(val)
            val *= base

    powers = sorted(powers)

    # Now we want number of ways to express n as sum of unique elements from powers

    # Use backtracking with memoization
    from functools import lru_cache

    @lru_cache(None)
    def dfs(i, target):
        if target == 0:
            return 1
        if target < 0 or i == len(powers):
            return 0
        # Two choices: include powers[i] or not
        return dfs(i+1, target - powers[i]) + dfs(i+1, target)

    return dfs(0, n)
